window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["pinterest"]={html:"<div class=\"own-pinterest\">\n  <a class=\"pt-skip\" href=\"#ptTop\">Skip to content</a>\n\n  <!-- ── NAV ─────────────────────────────────────────────────────────── -->\n  <header class=\"pt-nav\" id=\"ptNav\">\n    <div class=\"pt-nav-in\">\n      <a class=\"pt-brand\" href=\"#ptTop\" aria-label=\"Northwind home\">\n        <span class=\"pt-brand-mark\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\"><circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#e60023\"/><path d=\"M12 5.4a6.6 6.6 0 0 0-2.4 12.75c-.04-.55-.01-1.2.13-1.79l.85-3.6s-.21-.43-.21-1.07c0-1 .58-1.75 1.3-1.75.62 0 .92.46.92 1.02 0 .62-.4 1.55-.6 2.41-.17.72.36 1.3 1.07 1.3 1.29 0 2.28-1.36 2.28-3.32 0-1.73-1.24-2.95-3.02-2.95-2.06 0-3.27 1.55-3.27 3.15 0 .62.24 1.29.54 1.65a.22.22 0 0 1 .05.21l-.2.8c-.03.13-.1.16-.24.1-.9-.42-1.46-1.73-1.46-2.78 0-2.27 1.65-4.35 4.75-4.35 2.5 0 4.44 1.78 4.44 4.15 0 2.48-1.56 4.47-3.73 4.47-.73 0-1.41-.38-1.65-.82l-.45 1.7c-.16.62-.6 1.4-.9 1.87A6.6 6.6 0 1 0 12 5.4Z\" fill=\"#fff\"/></svg>\n        </span>\n        <span class=\"pt-brand-name\">Northwind</span>\n      </a>\n      <nav class=\"pt-nav-links\" aria-label=\"Primary\">\n        <a href=\"#ptProduct\">Explore</a>\n        <a href=\"#ptBoard\">Boards</a>\n        <a href=\"#ptPricing\">Pricing</a>\n        <a href=\"#ptStories\">Customers</a>\n      </nav>\n      <form class=\"pt-search\" role=\"search\" onsubmit=\"return false\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg>\n        <input type=\"search\" placeholder=\"Search for ideas, dashboards, teams\" aria-label=\"Search\">\n      </form>\n      <div class=\"pt-nav-actions\">\n        <a class=\"pt-btn pt-btn-tertiary\" href=\"#\">Log in</a>\n        <a class=\"pt-btn pt-btn-primary\" href=\"#ptPricing\">Sign up</a>\n      </div>\n    </div>\n  </header>\n\n  <main id=\"ptTop\">\n    <!-- ── HERO ───────────────────────────────────────────────────────── -->\n    <section class=\"pt-hero\">\n      <div class=\"pt-wrap pt-hero-in\">\n        <p class=\"pt-eyebrow\">Northwind · operations analytics</p>\n        <h1 class=\"pt-hero-title\">Create the ops picture<br>you'll act on every day.</h1>\n        <p class=\"pt-hero-lead\">Northwind turns regions, throughput, and revenue into one warm, quiet canvas. Pin the dashboards that matter and let the numbers get out of the way.</p>\n        <div class=\"pt-hero-cta\">\n          <a class=\"pt-btn pt-btn-primary pt-btn-lg\" href=\"#ptPricing\">Get started — free</a>\n          <a class=\"pt-btn pt-btn-secondary pt-btn-lg\" href=\"#ptProduct\">See how it works</a>\n        </div>\n        <p class=\"pt-hero-note\">Free for 3 seats · No credit card · SOC 2 Type II</p>\n      </div>\n\n      <!-- masonry showcase -->\n      <div class=\"pt-masonry\" id=\"ptMasonry\" aria-label=\"Northwind dashboard pins\"></div>\n    </section>\n\n    <!-- ── FEATURE ROW (alternating) ──────────────────────────────────── -->\n    <section class=\"pt-section\" id=\"ptProduct\">\n      <div class=\"pt-wrap\">\n        <div class=\"pt-sec-head\">\n          <p class=\"pt-eyebrow\">What teams build</p>\n          <h2 class=\"pt-sec-title\">Bring your favorite metrics to life</h2>\n        </div>\n\n        <article class=\"pt-feature\">\n          <div class=\"pt-feature-art pt-art-a\" aria-hidden=\"true\">\n            <div class=\"pt-art-tile\"><span class=\"pt-metric\">$48.2k</span><span class=\"pt-metric-lab\">Revenue · weekly</span>\n              <svg viewBox=\"0 0 320 90\" preserveAspectRatio=\"none\"><path d=\"M0 70 L45 62 L90 68 L135 44 L180 50 L225 26 L270 32 L320 14\" fill=\"none\" stroke=\"#e60023\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n            </div>\n            <span class=\"pt-overlay-pill\">Revenue pulse</span>\n          </div>\n          <div class=\"pt-feature-copy\">\n            <h3 class=\"pt-feature-title\">Pins that update with the work</h3>\n            <p class=\"pt-feature-body\">Every shipment, ticket, and revenue line is a pin on a board. Move the work and the metric moves with it — no separate spreadsheet to reconcile.</p>\n            <a class=\"pt-btn pt-btn-primary\" href=\"#ptBoard\">Explore the boards</a>\n          </div>\n        </article>\n\n        <article class=\"pt-feature pt-feature-rev\">\n          <div class=\"pt-feature-art pt-art-b\" aria-hidden=\"true\">\n            <div class=\"pt-art-tile pt-art-dark\"><span class=\"pt-metric\">98.4%</span><span class=\"pt-metric-lab\">On-time throughput</span>\n              <div class=\"pt-bars\"><i style=\"height:40%\"></i><i style=\"height:64%\"></i><i style=\"height:52%\"></i><i style=\"height:80%\"></i><i style=\"height:68%\"></i><i style=\"height:94%\"></i></div>\n            </div>\n            <span class=\"pt-overlay-pill\">Throughput</span>\n          </div>\n          <div class=\"pt-feature-copy\">\n            <h3 class=\"pt-feature-title\">Six regions, one calm board</h3>\n            <p class=\"pt-feature-body\">Compare throughput across regions at a glance. Northwind keeps every region on the same ledger so a change in one shows up in the others instantly.</p>\n            <a class=\"pt-btn pt-btn-secondary\" href=\"#ptStories\">Read the story</a>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <!-- ── CATEGORY TILES ─────────────────────────────────────────────── -->\n    <section class=\"pt-section\" id=\"ptBoard\">\n      <div class=\"pt-wrap\">\n        <div class=\"pt-sec-head\">\n          <p class=\"pt-eyebrow\">Start from a board</p>\n          <h2 class=\"pt-sec-title\">The pins every ops team needs</h2>\n        </div>\n        <div class=\"pt-cat-grid\" id=\"ptCatGrid\"></div>\n      </div>\n    </section>\n\n    <!-- ── DARK CTA STRIP ─────────────────────────────────────────────── -->\n    <section class=\"pt-cta\" id=\"ptPricing\">\n      <div class=\"pt-wrap pt-cta-in\">\n        <div>\n          <p class=\"pt-cta-eyebrow\">Northwind for your team</p>\n          <h2 class=\"pt-cta-title\">Put the whole operation on one board.</h2>\n        </div>\n        <a class=\"pt-btn pt-btn-primary pt-btn-lg\" href=\"#\">Start free</a>\n      </div>\n    </section>\n\n    <!-- ── TESTIMONIAL / STORIES ──────────────────────────────────────── -->\n    <section class=\"pt-section\" id=\"ptStories\">\n      <div class=\"pt-wrap\">\n        <div class=\"pt-sec-head\">\n          <p class=\"pt-eyebrow\">From the floor</p>\n          <h2 class=\"pt-sec-title\">Teams pinning with Northwind</h2>\n        </div>\n        <div class=\"pt-quotes\" id=\"ptQuotes\"></div>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER ───────────────────────────────────────────────────────── -->\n  <footer class=\"pt-foot\">\n    <div class=\"pt-wrap\">\n      <div class=\"pt-foot-grid\">\n        <div>\n          <p class=\"pt-foot-head\">Get the app</p>\n          <a href=\"#\">iOS</a><a href=\"#\">Android</a>\n        </div>\n        <div>\n          <p class=\"pt-foot-head\">Quick links</p>\n          <a href=\"#ptProduct\">Explore</a><a href=\"#ptBoard\">Boards</a><a href=\"#ptPricing\">Pricing</a>\n        </div>\n        <div>\n          <p class=\"pt-foot-head\">Northwind for</p>\n          <a href=\"#\">Logistics teams</a><a href=\"#\">Revenue ops</a><a href=\"#\">Support</a>\n        </div>\n        <div>\n          <p class=\"pt-foot-head\">About</p>\n          <a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Help center</a>\n        </div>\n      </div>\n      <div class=\"pt-foot-bottom\">\n        <span class=\"pt-foot-brand\">Northwind</span>\n        <span>© 2026 · Sample data — showcase only</span>\n      </div>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ PINTEREST — Northwind operations analytics, built in Pinterest's real page grammar ══\n   Warm-cream chrome, single Pinterest-Red CTA, Pin Sans display, masonry pin grid, 16px\n   radius everywhere. Everything scoped under `.own-pinterest`. */\n\n.own-pinterest {\n  --primary: #e60023;\n  --primary-pressed: #cc001f;\n  --on-primary: #ffffff;\n  --ink: #000000;\n  --ink-soft: #211922;\n  --body: #33332e;\n  --charcoal: #262622;\n  --mute: #62625b;\n  --ash: #91918c;\n  --stone: #c8c8c1;\n  --hairline: #dadad3;\n  --hairline-soft: #e5e5e0;\n  --canvas: #ffffff;\n  --surface-soft: #fbfbf9;\n  --surface-card: #f6f6f3;\n  --secondary-bg: #e5e5e0;\n  --secondary-pressed: #c8c8c1;\n  --surface-dark: #262622;\n  --on-dark: #ffffff;\n  --focus-outer: #435ee5;\n\n  --f-display: 'Pin Sans', 'Inter', -apple-system, system-ui, 'Segoe UI', Roboto, sans-serif;\n  --f-body: 'Pin Sans', 'Inter', -apple-system, system-ui, 'Segoe UI', Roboto, sans-serif;\n\n  --r-sm: 8px;\n  --r-md: 16px;\n  --r-lg: 32px;\n  --r-full: 9999px;\n  --gut: clamp(16px, 4.5cqi, 40px);\n  --sec: clamp(40px, 7cqi, 64px);\n\n  position: relative;\n  background: var(--surface-soft);\n  color: var(--body);\n  font-family: var(--f-body);\n  font-size: 16px;\n  line-height: 1.4;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n\n.own-pinterest *, .own-pinterest *::before, .own-pinterest *::after { box-sizing: border-box; }\n.own-pinterest p { margin: 0; }\n.own-pinterest h1, .own-pinterest h2, .own-pinterest h3 { margin: 0; }\n.own-pinterest a { color: inherit; text-decoration: none; }\n.own-pinterest img, .own-pinterest svg { display: block; }\n.own-pinterest button { font: inherit; }\n.own-pinterest :focus-visible { outline: 2px solid var(--focus-outer); outline-offset: 3px; border-radius: 6px; }\n\n.own-pinterest .pt-wrap { width: 100%; max-width: 1280px; margin: 0 auto; padding: 0 var(--gut); }\n\n.own-pinterest .pt-skip {\n  position: absolute; left: 12px; top: -60px; z-index: 60;\n  padding: 10px 16px; border-radius: var(--r-md); background: var(--ink); color: var(--on-dark);\n  font-weight: 700; transition: top .2s;\n}\n.own-pinterest .pt-skip:focus { top: 12px; }\n\n/* ── shared type ─────────────────────────────────────────────────────── */\n.own-pinterest .pt-eyebrow {\n  font-size: 12px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase;\n  color: var(--mute); margin-bottom: 14px;\n}\n.own-pinterest .pt-sec-head { max-width: 720px; margin-bottom: clamp(24px, 4cqi, 40px); }\n.own-pinterest .pt-sec-title {\n  font-family: var(--f-display); font-size: clamp(28px, 4.2cqi, 44px); font-weight: 700;\n  line-height: 1.15; letter-spacing: -.8px; color: var(--ink);\n}\n.own-pinterest .pt-hero-title {\n  font-family: var(--f-display); font-size: clamp(38px, 6.4cqi, 70px); font-weight: 600;\n  line-height: 1.1; letter-spacing: -1.2px; color: var(--ink);\n}\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-pinterest .pt-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 40px; padding: 6px 14px; border-radius: var(--r-md);\n  font-size: 14px; font-weight: 700; line-height: 1; white-space: nowrap;\n  transition: background-color .15s, transform .15s;\n}\n.own-pinterest .pt-btn-lg { height: 48px; padding: 6px 22px; font-size: 16px; }\n.own-pinterest .pt-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-pinterest .pt-btn-primary:hover { background: var(--primary-pressed); }\n.own-pinterest .pt-btn-primary:active { transform: scale(.97); }\n.own-pinterest .pt-btn-secondary { background: var(--secondary-bg); color: var(--ink); }\n.own-pinterest .pt-btn-secondary:hover { background: var(--secondary-pressed); }\n.own-pinterest .pt-btn-tertiary { background: transparent; color: var(--ink); padding: 6px 12px; }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-pinterest .pt-nav {\n  position: sticky; top: 68px; z-index: 40;\n  background: var(--canvas); border-bottom: 1px solid var(--hairline);\n}\n.own-pinterest .pt-nav-in {\n  display: flex; align-items: center; gap: 14px;\n  height: 64px; max-width: 1280px; margin: 0 auto; padding: 0 var(--gut);\n}\n.own-pinterest .pt-brand { display: flex; align-items: center; gap: 10px; flex: none; }\n.own-pinterest .pt-brand-mark { width: 28px; height: 28px; }\n.own-pinterest .pt-brand-name {\n  font-family: var(--f-display); font-size: 20px; font-weight: 700; letter-spacing: -.6px; color: var(--primary);\n}\n.own-pinterest .pt-nav-links { display: flex; gap: 4px; }\n.own-pinterest .pt-nav-links a {\n  font-size: 16px; font-weight: 600; color: var(--ink); padding: 8px 14px; border-radius: var(--r-full);\n}\n.own-pinterest .pt-nav-links a:hover { background: var(--surface-card); }\n.own-pinterest .pt-search {\n  flex: 1 1 auto; max-width: 480px; display: flex; align-items: center; gap: 10px;\n  height: 48px; padding: 11px 18px; border-radius: var(--r-full); background: var(--surface-card);\n}\n.own-pinterest .pt-search:focus-within { background: var(--canvas); box-shadow: inset 0 0 0 1px var(--ash); }\n.own-pinterest .pt-search svg { width: 18px; height: 18px; fill: none; stroke: var(--mute); stroke-width: 2; flex: none; }\n.own-pinterest .pt-search input {\n  width: 100%; border: 0; background: none; color: var(--ink); font: inherit; font-size: 16px; outline: none;\n}\n.own-pinterest .pt-search input::placeholder { color: var(--ash); }\n.own-pinterest .pt-nav-actions { display: flex; align-items: center; gap: 8px; flex: none; }\n\n/* ── hero ────────────────────────────────────────────────────────────── */\n.own-pinterest .pt-hero { padding-top: clamp(40px, 6cqi, 72px); }\n.own-pinterest .pt-hero-in { max-width: 760px; margin: 0 auto; text-align: center; padding-bottom: clamp(28px, 4cqi, 44px); }\n.own-pinterest .pt-hero-lead {\n  font-size: clamp(16px, 1.5cqi, 18px); line-height: 1.5; color: var(--body);\n  max-width: 56ch; margin: 20px auto 0;\n}\n.own-pinterest .pt-hero-cta { display: flex; gap: 12px; justify-content: center; margin-top: 26px; }\n.own-pinterest .pt-hero-note { font-size: 14px; color: var(--mute); margin-top: 16px; }\n\n/* ── masonry ─────────────────────────────────────────────────────────── */\n.own-pinterest .pt-masonry {\n  columns: 5; column-gap: 8px; width: 100%; padding: 0 var(--gut) 8px; max-width: 1440px; margin: 0 auto;\n}\n.own-pinterest .pt-pin {\n  position: relative; break-inside: avoid; margin-bottom: 8px; border-radius: var(--r-md);\n  overflow: hidden; background: var(--surface-card); isolation: isolate;\n}\n.own-pinterest .pt-pin > svg, .own-pinterest .pt-pin > .pt-pin-art { display: block; width: 100%; }\n.own-pinterest .pt-pin-art { display: grid; place-items: center; padding: 18px; min-height: 150px; }\n.own-pinterest .pt-pin-art .pt-pin-num {\n  font-family: var(--f-display); font-size: 34px; font-weight: 700; letter-spacing: -1px; color: #fff;\n}\n.own-pinterest .pt-pin-art .pt-pin-lab { font-size: 12px; font-weight: 600; color: rgba(255,255,255,.85); margin-top: 4px; }\n.own-pinterest .pt-pin-art .pt-spark { width: 100%; height: 56px; }\n.own-pinterest .pt-pin-art .pt-spark path { fill: none; stroke: #fff; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }\n.own-pinterest .pt-pin-art .pt-donut { width: 70px; height: 70px; }\n.own-pinterest .pt-pin-art .pt-donut circle { fill: none; stroke-width: 10; }\n.own-pinterest .pt-pin-art .pt-bars2 { display: flex; align-items: flex-end; gap: 6px; height: 64px; width: 100%; }\n.own-pinterest .pt-pin-art .pt-bars2 i { flex: 1; border-radius: 4px; background: rgba(255,255,255,.9); }\n.own-pinterest .pt-overlay-pill {\n  position: absolute; left: 12px; bottom: 12px; z-index: 2;\n  padding: 6px 12px; border-radius: var(--r-full); background: var(--canvas); color: var(--ink);\n  font-size: 12px; font-weight: 700;\n}\n\n/* ── feature rows ────────────────────────────────────────────────────── */\n.own-pinterest .pt-section { padding: var(--sec) 0; }\n.own-pinterest .pt-feature {\n  display: grid; grid-template-columns: 1fr 1fr; gap: clamp(24px, 4cqi, 56px); align-items: center;\n  margin-bottom: clamp(28px, 4cqi, 48px);\n}\n.own-pinterest .pt-feature-rev .pt-feature-art { order: 2; }\n.own-pinterest .pt-feature-art {\n  position: relative; border-radius: var(--r-lg); overflow: hidden; min-height: 320px;\n  display: grid; place-items: center; padding: 32px;\n}\n.own-pinterest .pt-art-a { background: linear-gradient(135deg, #fff0f3 0%, var(--secondary-bg) 100%); }\n.own-pinterest .pt-art-b { background: linear-gradient(135deg, #eef4ff 0%, var(--surface-card) 100%); }\n.own-pinterest .pt-art-tile {\n  width: 100%; max-width: 360px; background: var(--canvas); border-radius: var(--r-md);\n  padding: 22px; box-shadow: 0 16px 40px -28px rgba(0,0,0,.4);\n}\n.own-pinterest .pt-art-tile.pt-art-dark { background: var(--surface-dark); color: var(--on-dark); }\n.own-pinterest .pt-metric { display: block; font-family: var(--f-display); font-size: 40px; font-weight: 700; letter-spacing: -1.2px; }\n.own-pinterest .pt-metric-lab { display: block; font-size: 13px; font-weight: 600; color: var(--mute); margin: 2px 0 14px; }\n.own-pinterest .pt-art-dark .pt-metric-lab { color: rgba(255,255,255,.7); }\n.own-pinterest .pt-art-tile svg { width: 100%; height: 70px; }\n.own-pinterest .pt-bars { display: flex; align-items: flex-end; gap: 8px; height: 70px; }\n.own-pinterest .pt-bars i { flex: 1; border-radius: 6px; background: var(--primary); }\n.own-pinterest .pt-feature-title {\n  font-family: var(--f-display); font-size: clamp(24px, 3cqi, 32px); font-weight: 700;\n  letter-spacing: -.8px; line-height: 1.2; color: var(--ink); margin-bottom: 14px;\n}\n.own-pinterest .pt-feature-body { font-size: 16px; line-height: 1.5; color: var(--body); max-width: 46ch; margin-bottom: 22px; }\n\n/* ── category tiles ──────────────────────────────────────────────────── */\n.own-pinterest .pt-cat-grid {\n  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;\n}\n.own-pinterest .pt-cat {\n  position: relative; border-radius: var(--r-md); overflow: hidden; background: var(--surface-card);\n  min-height: 190px; display: flex; flex-direction: column; justify-content: flex-end; padding: 18px;\n  isolation: isolate;\n}\n.own-pinterest .pt-cat::before {\n  content: ''; position: absolute; inset: 0; z-index: -1; opacity: .92;\n  background: var(--c, var(--primary));\n}\n.own-pinterest .pt-cat-glyph { font-family: var(--f-display); font-size: 34px; font-weight: 700; color: rgba(255,255,255,.5); margin-bottom: auto; }\n.own-pinterest .pt-cat-name { font-size: 16px; font-weight: 600; color: #fff; }\n.own-pinterest .pt-cat-count { font-size: 13px; color: rgba(255,255,255,.82); margin-top: 2px; }\n\n/* ── dark CTA strip ──────────────────────────────────────────────────── */\n.own-pinterest .pt-cta { background: var(--surface-dark); color: var(--on-dark); }\n.own-pinterest .pt-cta-in {\n  display: flex; align-items: center; justify-content: space-between; gap: 24px;\n  padding: clamp(32px, 5cqi, 48px) 0; flex-wrap: wrap;\n}\n.own-pinterest .pt-cta-eyebrow { font-size: 12px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: rgba(255,255,255,.7); margin-bottom: 10px; }\n.own-pinterest .pt-cta-title {\n  font-family: var(--f-display); font-size: clamp(24px, 3.4cqi, 34px); font-weight: 700; letter-spacing: -1px; line-height: 1.2;\n}\n\n/* ── quotes ──────────────────────────────────────────────────────────── */\n.own-pinterest .pt-quotes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.own-pinterest .pt-quote {\n  background: var(--canvas); border-radius: var(--r-md); padding: 24px; display: flex; flex-direction: column; gap: 18px;\n}\n.own-pinterest .pt-quote-text { font-size: 16px; line-height: 1.5; color: var(--body); }\n.own-pinterest .pt-quote-who { display: flex; align-items: center; gap: 12px; margin-top: auto; }\n.own-pinterest .pt-quote-av {\n  width: 40px; height: 40px; border-radius: var(--r-full); display: grid; place-items: center;\n  background: var(--primary); color: #fff; font-size: 14px; font-weight: 700; flex: none;\n}\n.own-pinterest .pt-quote-name { font-size: 14px; font-weight: 700; color: var(--ink); }\n.own-pinterest .pt-quote-role { font-size: 12px; color: var(--mute); }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-pinterest .pt-foot { background: var(--canvas); border-top: 1px solid var(--hairline); padding: 32px 0; }\n.own-pinterest .pt-foot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-pinterest .pt-foot-grid > div { display: flex; flex-direction: column; gap: 10px; }\n.own-pinterest .pt-foot-head { font-size: 14px; font-weight: 700; color: var(--ink); margin: 0 0 4px; }\n.own-pinterest .pt-foot-grid a { font-size: 14px; color: var(--mute); }\n.own-pinterest .pt-foot-grid a:hover { color: var(--ink); }\n.own-pinterest .pt-foot-bottom {\n  display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\n  margin-top: 28px; padding-top: 20px; border-top: 1px solid var(--hairline); font-size: 12px; color: var(--mute);\n}\n.own-pinterest .pt-foot-brand { font-family: var(--f-display); font-weight: 700; letter-spacing: -.6px; color: var(--primary); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-pinterest .pt-masonry { columns: 3; }\n  .own-pinterest .pt-cat-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-pinterest .pt-nav-links { display: none; }\n}\n@container frame (max-width: 760px) {\n  .own-pinterest .pt-masonry { columns: 2; }\n  .own-pinterest .pt-feature { grid-template-columns: 1fr; }\n  .own-pinterest .pt-feature-rev .pt-feature-art { order: 0; }\n  .own-pinterest .pt-feature-art { min-height: 240px; padding: 22px; }\n  .own-pinterest .pt-quotes { grid-template-columns: 1fr; }\n  .own-pinterest .pt-foot-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-pinterest .pt-search { display: none; }\n  .own-pinterest .pt-nav-in { height: auto; padding: 10px var(--gut); flex-wrap: wrap; }\n  .own-pinterest .pt-brand { order: 1; }\n  .own-pinterest .pt-nav-actions { order: 2; margin-left: auto; }\n  .own-pinterest .pt-nav-links {\n    display: flex; order: 3; width: 100%; justify-content: center; border-top: 1px solid var(--hairline-soft); padding-top: 8px;\n  }\n}\n@container frame (max-width: 430px) {\n  .own-pinterest .pt-masonry { columns: 1; }\n  .own-pinterest .pt-cat-grid { grid-template-columns: 1fr; }\n  .own-pinterest .pt-hero-cta { flex-direction: column; }\n  .own-pinterest .pt-hero-cta .pt-btn { width: 100%; }\n  .own-pinterest .pt-cta-in { flex-direction: column; align-items: flex-start; }\n  .own-pinterest .pt-nav-actions .pt-btn-tertiary { display: none; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-pinterest *, .own-pinterest *::before, .own-pinterest *::after {\n    animation-duration: .001ms !important; transition-duration: .001ms !important;\n  }\n}\n"};
/* ══ PINTEREST — Northwind operations analytics ═══════════════════════════════════
   Registers window.OWN_LAYOUTS['pinterest'].init(root). Renders the masonry pin
   grid, category tiles and quote cards from sample data. Returns a no-op cleanup
   (this layout is static — the cleanup exists so unmount stays safe). */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  /* Sample pins — fictional ops boards. height = masonry aspect. */
  var PINS = [
    { art: 'metric', c: '#e60023', num: '$48.2k', lab: 'Revenue · weekly', h: 210, pill: 'Revenue' },
    { art: 'spark', c: '#7e238b', h: 260, pill: 'Trend' },
    { art: 'donut', c: '#262622', pct: 82, h: 190, pill: 'SLA' },
    { art: 'bars', c: '#0057b8', h: 240, pill: 'Regions' },
    { art: 'metric', c: '#2c8c66', num: '98.4%', lab: 'On-time throughput', h: 190, pill: 'Throughput' },
    { art: 'spark', c: '#d53b00', h: 230, pill: 'Volume' },
    { art: 'donut', c: '#7e238b', pct: 64, h: 210, pill: 'Capacity' },
    { art: 'bars', c: '#211922', h: 250, pill: 'Backlog' },
    { art: 'metric', c: '#0057b8', num: '6', lab: 'Regions live', h: 180, pill: 'Regions' },
    { art: 'spark', c: '#e60023', h: 220, pill: 'Cycle time' }
  ];

  var CATS = [
    { c: '#e60023', name: 'Revenue pulse', count: '28 pins', d: 'M4 14 L10 9 L15 12 L21 5' },
    { c: '#262622', name: 'Throughput', count: '41 pins', d: 'M4 12h16M14 7l5 5-5 5' },
    { c: '#7e238b', name: 'Regions', count: '19 pins', d: 'M12 3a9 9 0 1 0 0 18a9 9 0 0 0 0-18M3 12h18M12 3c3 4 3 14 0 18M12 3c-3 4-3 14 0 18' },
    { c: '#0057b8', name: 'Support health', count: '33 pins', d: 'M12 4v16M4 12h16' },
    { c: '#2c8c66', name: 'Forecasting', count: '24 pins', d: 'M4 18 L10 12 L14 15 L20 6' },
    { c: '#d53b00', name: 'Inventory', count: '17 pins', d: 'M4 6h16v4H4zM4 14h16v4H4z' },
    { c: '#211922', name: 'Delivery SLAs', count: '22 pins', d: 'M12 4a8 8 0 1 0 0 16a8 8 0 0 0 0-16M12 8v4l3 2' },
    { c: '#617bff', name: 'Team capacity', count: '30 pins', d: 'M12 5a7 7 0 1 0 0 14a7 7 0 0 0 0-14M12 9a3 3 0 1 0 0 6a3 3 0 0 0 0-6' }
  ];

  var QUOTES = [
    { text: 'We pinned the whole quarter on one board. Throughput and revenue finally tell the same story.', name: 'Jo Alcantara', role: 'Head of Operations', i: 'JA' },
    { text: 'Northwind replaced four spreadsheets and a weekly reconciliation call. The numbers just stay in sync.', name: 'Mika Navarro', role: 'Revenue Ops Lead', i: 'MN' },
    { text: 'Regional leads open the same board every morning. No one argues about whose dashboard is right anymore.', name: 'Dane Ocampo', role: 'Logistics Manager', i: 'DO' }
  ];

  function pinArt(p) {
    if (p.art === 'metric') {
      return '<div class="pt-pin-art" style="background:' + esc(p.c) + ';min-height:' + p.h + 'px">'
        + '<span class="pt-pin-num">' + esc(p.num) + '</span>'
        + '<span class="pt-pin-lab">' + esc(p.lab) + '</span></div>';
    }
    if (p.art === 'spark') {
      return '<div class="pt-pin-art" style="background:' + esc(p.c) + ';min-height:' + p.h + 'px">'
        + '<svg class="pt-spark" viewBox="0 0 240 56" preserveAspectRatio="none" aria-hidden="true">'
        + '<path d="M0 46 L40 40 L80 44 L120 26 L160 32 L200 16 L240 20"/></svg>'
        + '<span class="pt-pin-lab" style="margin-top:12px">weekly trend</span></div>';
    }
    if (p.art === 'donut') {
      var off = Math.round(p.pct * 1.76);
      return '<div class="pt-pin-art" style="background:' + esc(p.c) + ';min-height:' + p.h + 'px">'
        + '<svg class="pt-donut" viewBox="0 0 80 80" aria-hidden="true">'
        + '<circle cx="40" cy="40" r="28" stroke="rgba(255,255,255,.22)"/>'
        + '<circle cx="40" cy="40" r="28" stroke="#fff" stroke-dasharray="176" stroke-dashoffset="' + (176 - off) + '" transform="rotate(-90 40 40)"/></svg>'
        + '<span class="pt-pin-num" style="font-size:22px;margin-top:8px">' + p.pct + '%</span></div>';
    }
    return '<div class="pt-pin-art" style="background:' + esc(p.c) + ';min-height:' + p.h + 'px">'
      + '<div class="pt-bars2" aria-hidden="true">' + [40, 66, 52, 84, 60, 92, 74].map(function (h) {
        return '<i style="height:' + h + '%"></i>';
      }).join('') + '</div>'
      + '<span class="pt-pin-lab" style="margin-top:12px">by region</span></div>';
  }

  OWN['pinterest'] = {
    init: function (root) {
      var $ = function (s) { return root.querySelector(s); };

      var masonry = $('#ptMasonry');
      if (masonry) {
        masonry.innerHTML = PINS.map(function (p) {
          return '<article class="pt-pin" aria-label="' + esc(p.pill) + ' pin">'
            + pinArt(p)
            + '<span class="pt-overlay-pill">' + esc(p.pill) + '</span></article>';
        }).join('');
      }

      var cats = $('#ptCatGrid');
      if (cats) {
        cats.innerHTML = CATS.map(function (c) {
          return '<a class="pt-cat" href="#" style="--c:' + esc(c.c) + '" aria-label="' + esc(c.name) + '">'
            + '<span class="pt-cat-glyph" aria-hidden="true"><svg viewBox="0 0 24 24" width="34" height="34" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="' + c.d + '"/></svg></span>'
            + '<span class="pt-cat-name">' + esc(c.name) + '</span>'
            + '<span class="pt-cat-count">' + esc(c.count) + '</span></a>';
        }).join('');
      }

      var quotes = $('#ptQuotes');
      if (quotes) {
        quotes.innerHTML = QUOTES.map(function (q) {
          return '<figure class="pt-quote">'
            + '<blockquote class="pt-quote-text">“' + esc(q.text) + '”</blockquote>'
            + '<figcaption class="pt-quote-who">'
            + '<span class="pt-quote-av" aria-hidden="true">' + esc(q.i) + '</span>'
            + '<span><span class="pt-quote-name">' + esc(q.name) + '</span><br>'
            + '<span class="pt-quote-role">' + esc(q.role) + '</span></span>'
            + '</figcaption></figure>';
        }).join('');
      }

      return function cleanup() { /* static layout — nothing to tear down */ };
    }
  };
})();
